    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or comp[r][c] != -1:
                continue
            stack = [(r, c)]
            comp[r][c] = cid
            markers = set()
            while stack:
                y, x = stack.pop()
                if grid[y][x] > 1:
                    markers.add(grid[y][x])
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and comp[ny][nx] == -1:
                        comp[ny][nx] = cid
                        stack.append((ny, nx))
            if markers:
                component_colors[cid] = min(markers)
            cid += 1

    # Color the interior cells: cells surrounded by nonzero cells in all 8 directions.
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            k = comp[r][c]
            if grid[r][c] != 1 or k not in component_colors:
                continue
            if all(grid[r + dr][c + dc] != 0
                   for dr in (-1, 0, 1) for dc in (-1, 0, 1)
                   if dr != 0 or dc != 0):
                out[r][c] = component_colors[k]

    return out
